function buildSpecialCategoryHtml(rawValue, row, universityName) {
  const name = clean(universityName || row?.university_name || row?.university_key);
  if (name === '경찰대학') return buildPoliceSpecialHtml();
  if (['육군사관학교', '해군사관학교', '공군사관학교', '국군간호사관학교'].includes(name)) return buildAcademySpecialHtml();
  if (SCIENCE_SPECIAL_DATA[name] || SCIENCE_SPECIAL_DATA[removeCampus(name)]) return buildScienceSpecialHtml(name);
  return buildPlainListHtml(splitAdmissionLines(rawValue), 'selection_method');
}

function buildSmartRawHtml(value, sectionKey, row = null, universityName = '') {
  if (row?.detail_status === 'category' && sectionKey === 'selection_method') {
    return buildSpecialCategoryHtml(value, row, universityName);
  }

  const lines = splitAdmissionLines(value).filter((line) => clean(line) !== '표 값');
  if (!lines.length) return '';

  if (sectionKey === 'previous_year_changes') return buildPreviousYearChangesHtml(lines, sectionKey);
  if (sectionKey === 'selection_method') return buildSelectionMethodHtml(lines, sectionKey);
  if (sectionKey === 'exam_schedule') return buildExamScheduleHtml(lines, sectionKey);
  if (sectionKey === 'minimum_requirements') return buildMinimumRequirementsHtml(lines, sectionKey);
  if (sectionKey === 'school_record_method') return buildStudentRecordHtml(lines, sectionKey);
  if (sectionKey === 'recruitment_quota') return buildRecruitmentHtml(lines, sectionKey);
  return buildPlainListHtml(lines, sectionKey);
}

function sanitizeExistingHtml(value) {
  return clean(value);
}

function wrapExistingHtml(value, sectionKey) {
  const html = sanitizeExistingHtml(value);
  if (!html) return '';

  const hasOwnNote = /admission-result-note|admission-section-note/.test(html);
  const note = hasOwnNote ? '' : `<div class="admission-result-note">${SECTION_NOTES[sectionKey] || ''}</div>`;

  return `
    <div class="admission-raw-section-wrap">
      ${note}
      <div class="admission-existing-html">
        ${html}
      </div>
    </div>
  `;
}


function buildSafeTextSectionHtml(value, sectionKey) {
  const text = splitAdmissionLines(value)
    .map((line) => sanitizeAdmissionDisplayText(line))
    .filter(Boolean)
    .join('\n');

  if (!text) return '';

  return sanitizeAdmissionRenderedHtml(withHwpSectionHeading(`
    <div class="admission-raw-section-wrap">
      <pre class="admission-raw-pre admission-safe-text-block">${escapeHtml(text)}</pre>
    </div>
  `, sectionKey));
}

function buildRawSectionHtml(value, sectionKey, row = null, universityName = '') {
  if (looksLikeHtml(value)) return sanitizeAdmissionRenderedHtml(value);
  if (sectionKey === 'recruitment_quota') return buildSafeTextSectionHtml(value, sectionKey);
  return sanitizeAdmissionRenderedHtml(withHwpSectionHeading(buildSmartRawHtml(value, sectionKey, row, universityName), sectionKey));
}

function buildRecruitmentResultHtml(value) {
  return buildSmartRawHtml(value, 'recruitment_quota');
}

function normalizeName(value) {
  return clean(value)
    .replace(/\s+/g, '')
    .replace(/[［\[]/g, '(')
    .replace(/[］\]]/g, ')')
    .toLowerCase();
}

function removeCampus(value) {
  return clean(value).replace(/\([^)]*\)/g, '');
}

function getFirstUrl(row, keys) {
  if (!row) return '';

  for (const key of keys) {
    const value = clean(row[key]);
    if (value) return value;
  }

  return '';
}


function getSectionText(row, key) {
  return clean(row?.[key]);
}

function ButtonLabel({ item }) {
  if (!item.lines) return <span className="whitespace-nowrap">{item.label}</span>;

  return (
    <span className="block text-center leading-[1.22]">
      {item.lines.map((line) => (
        <span key={line} className="block whitespace-nowrap">
          {line}
        </span>
      ))}
    </span>
  );
}

function getFullResourceName(row) {
  const name = clean(row?.university_name || row?.name);
  const campus = clean(row?.campus);

  if (!name) return '';
  if (!campus || name.includes('(')) return name;
  return `${name}(${campus})`;
}

function buildResourceIndex(rows) {
  const exactMap = new Map();
  const baseBucket = new Map();

  rows.forEach((row) => {
    const names = [
      row?.university_key,
      row?.university_name,
      row?.name,
      getFullResourceName(row)
    ]
      .map(clean)
      .filter(Boolean);

    names.forEach((name) => {
      exactMap.set(normalizeName(name), row);
    });

    const baseName = removeCampus(row?.university_name || row?.name);
    const baseKey = normalizeName(baseName);
    if (baseKey) {
      if (!baseBucket.has(baseKey)) baseBucket.set(baseKey, []);
      baseBucket.get(baseKey).push(row);
    }
  });

  const uniqueBaseMap = new Map();
  baseBucket.forEach((bucket, key) => {
    if (bucket.length === 1) uniqueBaseMap.set(key, bucket[0]);
  });

  return { exactMap, uniqueBaseMap };
}

function findResourceRow(university, resourceIndex) {
  const exactKey = normalizeName(university.name);
  const exact = resourceIndex.exactMap.get(exactKey);
  if (exact) return exact;

  const baseKey = normalizeName(removeCampus(university.name));
  return resourceIndex.uniqueBaseMap.get(baseKey) || null;
}


const HWP_SECTION_FIELD_KEYS = [
  'previous_year_changes',
  'selection_method',
  'minimum_requirements',
  'exam_schedule',
  'school_record_method',
  'recruitment_quota'
];

const HWP_SECTION_HTML_KEYS = [
  'previous_year_changes_html',
  'selection_method_html',
  'minimum_requirements_html',
  'exam_schedule_html',
  'school_record_method_html',
  'recruitment_result_html'
];

function findHwpSectionData(name) {
  const target = clean(name);
  if (!target) return null;

  if (admissionHwpSections[target]) return admissionHwpSections[target];

  const targetKey = normalizeName(target);
  return Object.values(admissionHwpSections).find((item) => {
    if (!item) return false;
    return normalizeName(item.university_name) === targetKey
      || normalizeName(item.hwp_source_name) === targetKey;
  }) || null;
}

function buildHwpResourceRow(universityName, hwpData) {
  const row = {
    university_name: universityName,
    name: universityName,
    detail_status: hwpData?.detail_status || 'normal',
    is_active: true,
    hwp_source_name: hwpData?.hwp_source_name || '',
    hwp_match_method: hwpData?.match_method || 'hwp'
  };

  HWP_SECTION_FIELD_KEYS.forEach((key) => {
    const value = clean(hwpData?.[key]);
    if (value) row[key] = value;
  });

  HWP_SECTION_HTML_KEYS.forEach((key) => {
    const value = clean(hwpData?.[key]);
    if (value) row[key] = value;
  });

  return row;
}

function mergeHwpResourceRows(rows) {
  const mergedMap = new Map();

  Object.entries(admissionHwpSections).forEach(([universityName, hwpData]) => {
    const hwpRow = buildHwpResourceRow(universityName, hwpData);
    const key = normalizeName(universityName);
    if (key) mergedMap.set(key, hwpRow);
  });

  (rows || []).forEach((originalRow) => {
    const fullName = getFullResourceName(originalRow) || clean(originalRow?.university_name || originalRow?.name);
    const hwpData = findHwpSectionData(fullName)
      || findHwpSectionData(originalRow?.university_name)
      || findHwpSectionData(originalRow?.name)
      || findHwpSectionData(originalRow?.university_key);

    const row = { ...originalRow };
    if (hwpData) {
      row.hwp_source_name = hwpData.hwp_source_name || row.hwp_source_name || '';
      row.hwp_match_method = hwpData.match_method || row.hwp_match_method || 'hwp';
      HWP_SECTION_FIELD_KEYS.forEach((key) => {
        const hwpValue = clean(hwpData[key]);
        if (hwpValue) row[key] = hwpValue;
      });
      HWP_SECTION_HTML_KEYS.forEach((key) => {
        const hwpValue = clean(hwpData[key]);
        if (hwpValue) row[key] = hwpValue;
      });
    }

    const key = normalizeName(getFullResourceName(row) || fullName);
    if (key) mergedMap.set(key, row);
  });

  return Array.from(mergedMap.values());
}

function InfoButton({ section, row, universityName, onOpen, compact = false }) {
  const rawTextContent = resolveSectionText(row, section);
  const htmlContent = section.htmlKey && !hasDifferentNumberedSectionOnly(stripHtmlToText(row?.[section.htmlKey]), section.key)
    ? clean(row?.[section.htmlKey])
    : '';
  const wrappedRawKeys = ['previous_year_changes', 'selection_method', 'minimum_requirements', 'exam_schedule', 'school_record_method', 'recruitment_quota'];
  const shouldWrapRaw = wrappedRawKeys.includes(section.key);
  const hasMeaningfulRaw = rawTextContent && rawTextContent.length >= 20;

  const hasHwpSource = Boolean(row?.hwp_match_method || row?.hwp_source_name || findHwpSectionData(universityName));
  const preferExistingHtmlKeys = ['minimum_requirements', 'exam_schedule', 'school_record_method', 'recruitment_quota'];
  const shouldPreferExistingHtml = Boolean(htmlContent) && preferExistingHtmlKeys.includes(section.key);
  const content = shouldPreferExistingHtml
    ? sanitizeAdmissionRenderedHtml(withHwpSectionHeading(`<div class="admission-existing-html">${htmlContent}</div>`, section.key))
    : (hasHwpSource && hasMeaningfulRaw
      ? buildRawSectionHtml(rawTextContent, section.key, row, universityName)
      : (htmlContent
        ? sanitizeAdmissionRenderedHtml(withHwpSectionHeading(`<div class="admission-existing-html">${htmlContent}</div>`, section.key))
        : (looksLikeHtml(rawTextContent)
          ? sanitizeAdmissionRenderedHtml(rawTextContent)
          : (hasMeaningfulRaw ? buildRawSectionHtml(rawTextContent, section.key, row, universityName) : rawTextContent))));
  const isHtmlContent = Boolean(content) && (shouldWrapRaw || looksLikeHtml(content));
  const baseClass = compact
    ? 'admission-table-action flex min-h-[34px] w-full items-center justify-center rounded-[7px] px-2 py-1.5 text-center text-[12px] font-black tracking-[-0.03em] transition'
    : 'flex min-h-[46px] items-center justify-center rounded-[10px] px-3 py-2 text-center text-[13px] font-black tracking-[-0.02em] transition';

  if (!content) {
    return (
      <span
        className={`${baseClass} cursor-not-allowed border border-[#D6DCE6] bg-[#F0F2F5] text-[#9EA7B3]`}
        title="등록된 정보가 없습니다."
      >
        <ButtonLabel item={section} />
      </span>
    );
  }

  return (
    <button
      type="button"
      onClick={() => onOpen(section, content, isHtmlContent)}
      className={`${baseClass} border border-[#1F3654] bg-[#14253D] text-white shadow-sm hover:border-[#C99A4B] hover:bg-[#C99A4B] hover:text-[#10243E]`}
      title={`${section.label} 보기`}
    >
      <ButtonLabel item={section} />
    </button>
  );
}

function LinkButton({ section, row, compact = false }) {
  const url = getFirstUrl(row, section.keys);
  const baseClass = compact
    ? `admission-table-action flex min-h-[34px] w-full items-center justify-center rounded-[7px] px-2 py-1.5 text-center text-[12px] font-black tracking-[-0.03em] transition ${section.wide ? 'col-span-2' : ''}`
    : `flex min-h-[46px] items-center justify-center rounded-[10px] px-3 py-2 text-center text-[13px] font-black tracking-[-0.02em] transition ${section.wide ? 'col-span-2' : ''}`;

  if (!url) {
    return (
      <span
        className={`${baseClass} cursor-not-allowed border border-[#D6DCE6] bg-[#F0F2F5] text-[#9EA7B3]`}
        title="정시모집요강 URL이 아직 등록되지 않았습니다."
      >
        <ButtonLabel item={section} />
      </span>
    );
  }

  return (
    <a
      href={url}
      target="_blank"
      rel="noreferrer"
      className={`${baseClass} border border-[#C99A4B] bg-[#FFF7E8] text-[#7A5418] shadow-sm hover:border-[#14253D] hover:bg-[#14253D] hover:text-white`}
      title={`${section.label} 열기`}
    >
      <ButtonLabel item={section} />
    </a>
  );
}

function openUniversityInfo(onOpenInfo, university, openedSection, content, isHtml = false) {
  onOpenInfo({
    universityName: university.name,
    title: openedSection.label,
    content,
    isHtml
  });
}

